import { nebulaLightingChunk } from './NebulaLighting'

// GLSL chunk: multichromatic self-emissive color + secondary ionization channel
// + stellar scattering. Dust has no self-emission.
// uAmbient is the self-emission baseline (default 1.0 -> visible without a star);
// the star adds scattered light, never darkens intrinsic emission.
// Scatter is WHITE by default: it scales the palette colour. With uLightTint the
// scatter term takes the star's hue instead; the ambient term is never tinted.
export const nebulaColorChunk = `
  ${nebulaLightingChunk}
  uniform vec3  uPalette0; uniform vec3 uPalette1; uniform vec3 uPalette2; uniform vec3 uPalette3;
  uniform vec4  uPaletteT;
  uniform vec3  uSecondaryColor;
  uniform float uSecondaryThreshold;
  uniform vec3  uDustColor;
  uniform float uAmbient;
  uniform vec3  uLightColor;
  uniform float uLightTint;
  uniform float uRadialMix;
  uniform vec3  uInnerColor;
  uniform vec3  uOuterColor;

  vec3 paletteLookup(float t) {
    vec3 c = uPalette0;
    c = mix(c, uPalette1, smoothstep(uPaletteT.x, uPaletteT.y, t));
    c = mix(c, uPalette2, smoothstep(uPaletteT.y, uPaletteT.z, t));
    c = mix(c, uPalette3, smoothstep(uPaletteT.z, uPaletteT.w, t));
    return c;
  }

  vec3 nebulaDustColor(float scatter) {
    // Dust only reflects the supplied star; ambient and gas emissivity do not
    // illuminate it. Its colour is a reflectance, not an emissive source.
    vec3 illumination = uLightTint > 0.5 ? uLightColor : vec3(1.0);
    return uDustColor * illumination * scatter;
  }

  vec3 nebulaGasColor(float density, vec3 p, float scatter) {
    vec3 base = paletteLookup(density);
    // secondary ionization channel: tint dense regions toward the accent color
    float sec = smoothstep(uSecondaryThreshold, 1.0, density);
    base = mix(base, uSecondaryColor, sec * 0.6);

    // Radial ionisation tint. Density answers "how thick"; in a planetary nebula
    // the colour answers a different question — "how ionised" — and that one is
    // radial: O III near the star, H-alpha further out, [N II] at the very rim.
    // Standing in for it with density only holds while the two are correlated,
    // which a knotted shell breaks.
    //
    // Gated on uRadialMix so the default (0) leaves every existing nebula byte
    // for byte as it was — this chunk is shared by all of them.
    //
    // p is proxy-local in [-1,1]^3, so length(p) reaches 1 on an axis and sqrt(3)
    // in a corner; the clamp flattens the corners. Good enough for a hue ramp —
    // it would NOT be for a hard boundary, which is why nebBoundary scales by
    // uInvAxis instead.
    if (uRadialMix > 0.001) {
      float radial = clamp(length(p), 0.0, 1.0);
      base = mix(base, mix(uInnerColor, uOuterColor, radial), uRadialMix);
    }
    // self-emission baseline (uAmbient) + optional directional forward scatter
    float light = uAmbient;
    vec3 tinted = vec3(0.0);
    // A coloured light replaces the scatter hue; ambient keeps the gas palette.
    if (uLightTint > 0.5) {
      tinted = uLightColor * dot(base, vec3(0.2126, 0.7152, 0.0722)) * scatter;
    } else {
      light += scatter;
    }
    return base * light + tinted;
  }
`

// Single-scattered stellar light. The caller adds intrinsic gas emission separately.
export const nebulaLightingChunk = `
  uniform float uDensityScale;
  uniform float uGasAbsorption;
  uniform float uDustStrength;
  uniform float uScatterStrength;
  uniform vec3  uStarLocal;
  uniform float uHasStar;
  uniform float uLightFalloff;
  uniform float uPhaseHG;
  uniform float uAnisotropy;
  uniform float uShadowStrength;
  uniform float uLightSteps;
  #ifdef NEB_BAKED_ONLY
    uniform float uDensityUnitRange;
  #endif

  float nebulaPhase(vec3 rd, vec3 toStar) {
    if (uPhaseHG < 0.5) return max(dot(-rd, toStar), 0.0);
    // rd points camera -> sample; toStar points sample -> star. Their dot is
    // the propagation cosine, positive for forward scattering toward the viewer.
    // 4*pi times normalized HG: g=0 gives a brightness multiplier of one.
    float cosine = clamp(dot(rd, toStar), -1.0, 1.0);
    float g = uAnisotropy;
    float denominator = 1.0 + g * g - 2.0 * g * cosine;
    return (1.0 - g * g) / (denominator * sqrt(denominator));
  }

  float nebulaLightTransmittance(vec3 p, vec3 toStar, float distanceToStar) {
    if (uShadowStrength <= 0.0 || distanceToStar <= 1e-6) return 1.0;
    if (uDensityScale * uGasAbsorption <= 0.0 && uDustStrength <= 0.0) return 1.0;
    // p is inside the density cube. Stop at the star if it is inside too,
    // otherwise at the first exit face. Explicit parallel-axis branches avoid
    // 0*infinity / NaN on a face and prevent sampling clamped texels outside it.
    float path = distanceToStar;
    if (toStar.x != 0.0) path = min(path, (sign(toStar.x) - p.x) / toStar.x);
    if (toStar.y != 0.0) path = min(path, (sign(toStar.y) - p.y) / toStar.y);
    if (toStar.z != 0.0) path = min(path, (sign(toStar.z) - p.z) / toStar.z);
    if (path <= 0.0) return 1.0;

    float dt = path / uLightSteps;
    float tau = 0.0;
    #ifdef NEB_BAKED_ONLY
      // Normalized samples cannot exceed this optical depth, including any
      // partial sum. Leave a full unit below the cutoff for rounding. Keeping
      // this loop separate removes its texture-dependent exit at every sample.
      float upperTau = (max(uDensityScale * uGasAbsorption, 0.0) + max(uDustStrength, 0.0)) * path * uShadowStrength;
      if (uDensityUnitRange > 0.5 && upperTau < 11.0) {
        for (int i = 0; i < 16; i++) {
          if (i >= int(uLightSteps)) break;
          vec2 medium = nebulaMedium(p + toStar * (float(i) + 0.5) * dt);
          float sigma = medium.r * uDensityScale * uGasAbsorption + medium.g * uDustStrength;
          tau += sigma * dt * uShadowStrength;
        }
        return exp(-tau);
      }
    #endif
    for (int i = 0; i < 16; i++) {
      if (i >= int(uLightSteps)) break;
      vec2 medium = nebulaMedium(p + toStar * (float(i) + 0.5) * dt);
      float sigma = medium.r * uDensityScale * uGasAbsorption + medium.g * uDustStrength;
      tau += sigma * dt * uShadowStrength;
      // Remaining transmission is below 0.000006; skip opaque light paths.
      if (tau >= 12.0) return 0.0;
    }
    return exp(-tau);
  }

  float nebulaStarLight(vec3 p, vec3 rd) {
    if (uHasStar < 0.5 || uScatterStrength <= 0.0) return 0.0;
    vec3 toStarVec = uStarLocal - p;
    float distanceToStar = length(toStarVec);
    vec3 toStar = toStarVec / max(distanceToStar, 1e-6);
    float scatter = uScatterStrength * nebulaPhase(rd, toStar);
    if (uLightFalloff > 0.001) {
      float q = distanceToStar / uLightFalloff;
      scatter /= 1.0 + q * q;
    }
    if (scatter <= 0.0) return 0.0;
    return scatter * nebulaLightTransmittance(p, toStar, distanceToStar);
  }
`

