// Disposable GPU diagnosis. Derive exact palettes from current live Float32 data.
import { DataTexture, FloatType, NearestFilter, RedFormat, RepeatWrapping, RGBAFormat, UnsignedByteType } from 'three'

export function createPaletteVariants(source: string, uniforms: any) {
  const full = uniforms.uDustClumpGradients.value.image.data as Float32Array
  const bits = new Uint32Array(full.buffer, full.byteOffset, full.length)
  const map = new Map<string, number>(), values: number[] = [], indices = new Uint8Array(full.length / 4)
  for (let i = 0; i < full.length; i += 4) {
    const key = `${bits[i]},${bits[i+1]},${bits[i+2]}`
    let index = map.get(key)
    if (index === undefined) { index = map.size; map.set(key, index); values.push(full[i],full[i+1],full[i+2],1) }
    indices[i/4] = index
  }
  if (map.size !== 49) throw Error('Unexpected gradient count')
  const indexMap = new DataTexture(indices, 289, 289, RedFormat, UnsignedByteType)
  indexMap.minFilter=NearestFilter;indexMap.magFilter=NearestFilter
  indexMap.wrapS=RepeatWrapping;indexMap.wrapT=RepeatWrapping;indexMap.generateMipmaps=false;indexMap.needsUpdate=true
  const palette = new DataTexture(new Float32Array(values),49,1,RGBAFormat,FloatType)
  palette.minFilter=NearestFilter;palette.magFilter=NearestFilter;palette.generateMipmaps=false;palette.needsUpdate=true
  uniforms.uDustClumpIndices={value:indexMap};uniforms.uDustClumpPalette={value:palette}
  uniforms.uDustClumpVectors={value:Float32Array.from(values.filter((_,i)=>i%4!==3))}
  const shader=(kind:'texture'|'uniform')=>{
    let text=source
    for(const component of ['x','y','z','w']){
      const from=`textureLod(uDustClumpGradients, (vec2(gx.${component}, gy.${component}) + 0.5) / 289.0, 0.0).xyz`
      if(!text.includes(from))throw Error('Missing gradient source marker')
      text=text.replace(from,`dustIndexedGradient((vec2(gx.${component}, gy.${component}) + 0.5) / 289.0)`)
    }
    return `uniform sampler2D uDustClumpIndices;
      ${kind==='texture'?'uniform sampler2D uDustClumpPalette;':'uniform vec3 uDustClumpVectors[49];'}
      vec3 dustIndexedGradient(vec2 uv) {
        float index = floor(textureLod(uDustClumpIndices, uv, 0.0).r * 255.0 + 0.5);
        return ${kind==='texture'?'textureLod(uDustClumpPalette, vec2((index+0.5)/49.0,0.5),0.0).xyz':'uDustClumpVectors[int(index)]'};
      }
      `+text
  }
  return {
    rows:[['indexTexturePalette',shader('texture')],['indexUniformPalette',shader('uniform')]] as [string,string][],
    metadata:{unique:map.size,indexBytes:indices.byteLength,paletteBytes:values.length*4,uniformBytes:uniforms.uDustClumpVectors.value.byteLength,originalBytes:full.byteLength},
    dispose(){indexMap.dispose();palette.dispose()}
  }
}

