// One-factor candidates: retain the legacy path for non-increasing stops.
export function candidateSources(source: string): [string,string][] {
  const marker='  vec3 paletteLookup(float t) {',ordered='uPaletteT.x < uPaletteT.y && uPaletteT.y < uPaletteT.z && uPaletteT.z < uPaletteT.w'
  if(!source.includes(marker))throw Error('Palette source marker missing')
  const piecewise=source.replace(marker,`${marker}
    if (${ordered}) {
      if (t < uPaletteT.y) return mix(uPalette0, uPalette1, smoothstep(uPaletteT.x, uPaletteT.y, t));
      if (t < uPaletteT.z) return mix(uPalette1, uPalette2, smoothstep(uPaletteT.y, uPaletteT.z, t));
      return mix(uPalette2, uPalette3, smoothstep(uPaletteT.z, uPaletteT.w, t));
    }`)
  const low=source.replace(marker,`${marker}
    if (${ordered} && t <= uPaletteT.y) return mix(uPalette0, uPalette1, smoothstep(uPaletteT.x, uPaletteT.y, t));`)
  return [['orderedPiecewisePalette',piecewise],['firstIntervalPalette',low]]
}

