  const screenshots = []
  for (const part of ['dust-palette-diagnosis', 'volume-parts-motion']) for (const id of [13, 12]) {
    const file = `${prefix}${part}-${date}-${id}.png`, b = await readFile(file)
    provenance.push({ path: file, bytes: b.length, sha256: hash(b) })
    screenshots.push({ path: file, sha256: hash(b), inspected: true, purpose: 'Scene presence/composition context; no before/after pixel claim' })
  }
  const original = normalize(execFileSync('git', ['show', `${base}:${productionPath}`], { encoding: 'utf8' }))
  let review
  try { await readFile(path('review') + '.json'); review = await source(path('review') + '.json') } catch (e) { if (e.code !== 'ENOENT') throw e }
  const archive = {
    schemaVersion: 1, createdAt: new Date().toISOString(), base,
    finding: { auditItem: 18, issue: 'Odd reflection puts a negative sign on decomposed worldScale.x and can understate the radius, changing transparent volume order.',
      fix: 'Use magnitudes of all three world-scale components in the existing far-edge ordering heuristic.',
      scope: 'Shared DepthVolumePass/LensFrontPass ordering. No new general-shear/intersection guarantee or invalid-input policy. No performance or cloud-scene pixel benefit claimed.' },
    baselineProof: { original, normalizedSha256: hash(original) },
    diagnosis: { dustPalette, nebulaPalette, volumeParts,
      decisions: 'Both dust palette variants and both nebula palette variants rejected: no speed gain. Nebula experiment failed the warning gate after Alkaid; W26 was not run. No shader changes accepted.',
      timingScope: '1280x720 DPR1 native AMD/Chrome155 cloud dev scenes. Volume GPU queries wrap renderBufferDirect, exclude surrounding render/resolve work. Instrumented CPU/frame intervals are not FPS or paired before/after evidence.',
      compaction: 'Volume profile embeds raw CPU/GPU/interval samples, summary, draw metadata and environment. Detailed instance/copy timelines remain in the hashed original.' },
    knownBaselineWarning, verification, logs, sourceSnapshots, screenshots, review, provenance
  }
  await verify(archive)
  await writeFile(destination, JSON.stringify(archive, null, 2) + '\n')
  console.log(destination)
}
